 static TextMesh Text(Transform p,string text,Vector3 at,float size){var g=New(p,text);g.localPosition=at;g.localRotation=Quaternion.Euler(0,180,0);var t=g.gameObject.AddComponent<TextMesh>();t.text=text;t.anchor=TextAnchor.MiddleCenter;t.alignment=TextAlignment.Center;t.fontSize=60;t.characterSize=size;t.color=Hex("E3C992");return t;}
