 static void Merge(Transform p,string name){var filters=p.GetComponentsInChildren<MeshFilter>().Where(f=>f.sharedMesh).ToArray();var groups=new Dictionary<Material,List<CombineInstance>>();foreach(var f in filters){var r=f.GetComponent<MeshRenderer>();if(!r)continue;for(int s=0;s<f.sharedMesh.subMeshCount;s++){var m=r.sharedMaterials[Math.Min(s,r.sharedMaterials.Length-1)];if(!groups.ContainsKey(m))groups[m]=new List<CombineInstance>();groups[m].Add(new CombineInstance{mesh=f.sharedMesh,subMeshIndex=s,transform=p.worldToLocalMatrix*f.transform.localToWorldMatrix});}}if(groups.Count==0)return;var pieces=new List<Mesh>();foreach(var g in groups){var mesh=new Mesh{indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(g.Value.ToArray(),true,true);pieces.Add(mesh);}var combined=new Mesh{indexFormat=IndexFormat.UInt32};combined.CombineMeshes(pieces.Select(m=>new CombineInstance{mesh=m,transform=Matrix4x4.identity}).ToArray(),false,true);combined.name=name;AssetDatabase.CreateAsset(combined,Root+"/Meshes/"+(meshId++)+"-"+name.Replace('/','-')+".asset");foreach(var f in filters){Object.DestroyImmediate(f.GetComponent<MeshRenderer>());Object.DestroyImmediate(f);}var target=New(p,"Batched salvage surfaces").gameObject;target.AddComponent<MeshFilter>().sharedMesh=combined;target.AddComponent<MeshRenderer>().sharedMaterials=groups.Keys.ToArray();foreach(var m in pieces)Object.DestroyImmediate(m);}
 static void Prefab(string key,Action<Transform> build){var p=New(null,key);build(p);Merge(p,key);foreach(var t in p.GetComponentsInChildren<Transform>())t.gameObject.isStatic=true;prefabs[key]=PrefabUtility.SaveAsPrefabAsset(p.gameObject,Root+"/Prefabs/"+key+".prefab");Object.DestroyImmediate(p.gameObject);}
 static void Prepare(){bevel=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/RoadGunner/Meshes/Scrap Rush beveled block.asset");rock=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/RoadGunner/Meshes/Scrap Rush boulder 0.asset");var primitive=GameObject.CreatePrimitive(PrimitiveType.Cylinder);cylinder=primitive.GetComponent<MeshFilter>().sharedMesh;Object.DestroyImmediate(primitive);
 Prefab("Corrugated fence",Fence);Prefab("Shipping container",Container);Prefab("Rusted lookout",Tower);Prefab("Abandoned pickup",p=>Wreck(p));Prefab("Bus wreck",p=>Wreck(p,true));Prefab("Damaged utility pole",Pole);Prefab("Closed scrap gate",p=>Gate(p,true));Prefab("Open scrap gate",p=>Gate(p,false));Prefab("Salvage gantry",Gantry);Prefab("Sealed industrial bunker",Door);Prefab("Scrap wind pump",WindPump);Prefab("Tire and scrap pile",Scrap);Prefab("Fuel drums",p=>{Drum(p,Vector3.zero);Drum(p,new Vector3(.9f,0,.3f));});Prefab("Tire stack",p=>{for(int i=0;i<3;i++)Tire(p,Vector3.up*i*.32f);});Prefab("Metal storage crate",p=>{Box(p,Vector3.up*.6f,new Vector3(1.2f,1.2f,1.2f),"Metal");for(int s=-1;s<=1;s+=2)Box(p,new Vector3(s*.35f,.62f,-.63f),new Vector3(.1f,1.2f,.08f),"Rust");});Prefab("Weathered concrete",p=>{Box(p,new Vector3(0,.85f,0),new Vector3(4,1.7f,1),"Concrete");Box(p,new Vector3(1.2f,1.4f,0),new Vector3(.7f,2.8f,1.3f),"Concrete");Solid(p,new Vector3(0,1.1f,0),new Vector3(4,2.2f,1.3f));});Prefab("Route sign",p=>Sign(p,"NORTH  /  DEPOT"));Prefab("Danger sign",p=>Sign(p,"DANGER"));Prefab("Scrap stakes",p=>{for(int i=0;i<4;i++)Beam(p,new Vector3(i*.7f-1,0,0),new Vector3(i*.7f-1,1.5f,.4f),.13f,"Rust");});Prefab("Dry scrub",p=>{for(int i=0;i<7;i++)Beam(p,Vector3.zero,new Vector3(Mathf.Sin(i*2.4f)*.55f,.4f+(i%3)*.15f,Mathf.Cos(i*2.4f)*.55f),.045f,"Dust");});
 Prefab("Service kiosk",p=>{Box(p,new Vector3(0,1,0),new Vector3(2,2,1.5f),"Rust");Box(p,new Vector3(0,1.45f,-.8f),new Vector3(1.4f,.6f,.1f),"Teal");Box(p,new Vector3(0,2.2f,0),new Vector3(2.6f,.16f,2),"Metal");Solid(p,new Vector3(0,1,0),new Vector3(2,2,1.5f));Sign(p,"SALVAGE");});
 }
 static string Replacement(string n){switch(n){case "Palisade":return "Corrugated fence";case "Tent":return "Shipping container";case "Watchtower":return "Rusted lookout";case "Covered Cart":return "Abandoned pickup";case "Blue Wreck":return "Bus wreck";case "Lantern":return "Damaged utility pole";case "Closed West Gate":case "Crystal North Gate":return "Closed scrap gate";case "Open South Gate":return "Open scrap gate";case "Stone Arch":return "Salvage gantry";case "Sealed Cliff Door":return "Sealed industrial bunker";case "Windmill":return "Scrap wind pump";case "Green Haired Guide":return "Service kiosk";case "Barrel":return "Fuel drums";case "Crate":return "Metal storage crate";case "Ruin":return "Weathered concrete";case "Skull Sign":return "Danger sign";case "Signpost":return "Route sign";case "Stakes":return "Scrap stakes";case "Bones":case "Planks":case "Mushroom Cluster":return "Tire and scrap pile";case "Fir":case "Bright Fir":case "Yellow Fir":case "Snow Fir":return "Tire stack";case "Bush":case "Yellow Bush":case "Grass Tuft":return "Dry scrub";default:return null;}}
 static void Recolor(Transform t){foreach(var r in t.GetComponentsInChildren<Renderer>(true)){r.sharedMaterials=r.sharedMaterials.Select(Remap).ToArray();if(PrefabUtility.IsPartOfPrefabInstance(r))PrefabUtility.RecordPrefabInstancePropertyModifications(r);}}
 static void StretchGeometry(Transform root){foreach(var f in root.GetComponentsInChildren<MeshFilter>()){var mesh=Object.Instantiate(f.sharedMesh);mesh.vertices=mesh.vertices.Select(X).ToArray();mesh.RecalculateBounds();mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,Root+"/Meshes/"+(meshId++)+"-expanded.asset");f.sharedMesh=mesh;}foreach(var c in root.GetComponentsInChildren<BoxCollider>()){c.center=X(c.center);c.size=X(c.size);}foreach(var t in root.GetComponentsInChildren<Transform>().Skip(1))t.localPosition=X(t.localPosition);}
 static Transform PlaceNew(string key,Transform parent,Vector3 position,Quaternion rotation,Vector3 scale){var g=(GameObject)PrefabUtility.InstantiatePrefab(prefabs[key],parent);g.transform.SetPositionAndRotation(position,rotation);g.transform.localScale=scale;PrefabUtility.RecordPrefabInstancePropertyModifications(g.transform);return g.transform;}
 static void ConvertSection(Transform section,bool obstacle){foreach(var t in section.Cast<Transform>().ToArray()){
 var oldPosition=t.position;var position=X(oldPosition);string prefabPath=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t);string source=Path.GetFileNameWithoutExtension(prefabPath);bool hasCollision=t.GetComponentsInChildren<Collider>().Any(c=>c.enabled&&!c.isTrigger);
 if(t.GetComponent<GreenwoodSanctuary>()||source=="Green Pool"){Object.DestroyImmediate(t.gameObject);Workshop(section,position);continue;}
 if(t.name.Contains("Guide question")){Object.DestroyImmediate(t.gameObject);continue;}
 if(source=="Cliff"){t.position=position;t.localScale=Vector3.Scale(t.localScale,new Vector3(2.5f,1,2.5f));Recolor(t);foreach(var c in t.GetComponentsInChildren<Collider>())PrefabUtility.RecordPrefabInstancePropertyModifications(c);PrefabUtility.RecordPrefabInstancePropertyModifications(t);continue;}
 string replacement=Replacement(source);if(replacement!=null){if(section.name.StartsWith("Cliff crown"))replacement="Dry scrub";var n=PlaceNew(replacement,section,position,t.rotation,t.localScale);if(!hasCollision)foreach(var c in n.GetComponentsInChildren<Collider>()){c.enabled=false;PrefabUtility.RecordPrefabInstancePropertyModifications(c);}Object.DestroyImmediate(t.gameObject);continue;}
 t.position=position;
 if(t.name=="Outer safety collision"||t.name=="Cliff foundation"||t.name.Contains("biome glimpse")||t.name.Contains("champion clearing"))StretchGeometry(t);
 if(t.name.Contains("Snow biome"))t.name="Pale salt-flat beyond locked gate";if(t.name.Contains("Quiet grass"))t.name="Wind-eroded earth patch";
 Recolor(t);
 }}
