 // Open drive-through apron. Side furniture stays outside the circular service zone.
 for(int s=-1;s<=1;s+=2){for(int z=-1;z<=1;z+=2){Box(p,new Vector3(s*10.8f,2.8f,z*6),new Vector3(.38f,5.6f,.45f),"Metal");Solid(p,new Vector3(s*10.8f,2.8f,z*6),new Vector3(.38f,5.6f,.45f));}Box(p,new Vector3(s*9.8f,5.7f,0),new Vector3(3.1f,.2f,13.5f),"Rust",new Vector3(0,0,s*5));Box(p,new Vector3(s*11.7f,1.1f,0),new Vector3(.2f,2.2f,9),"Rust");Solid(p,new Vector3(s*11.7f,1.1f,0),new Vector3(.2f,2.2f,9));}
 Box(p,new Vector3(0,5.8f,6),new Vector3(22,.35f,.5f),"Metal");Box(p,new Vector3(0,5.8f,-6),new Vector3(22,.35f,.5f),"Metal");Box(p,new Vector3(0,5.7f,-6.25f),new Vector3(7,1.2f,.16f),"Rust");Text(p,"AUTO REPAIR",new Vector3(0,5.7f,-6.4f),.46f);
 for(int i=0;i<3;i++){Drum(p,new Vector3(11,0,-3+i*1.1f));Tire(p,new Vector3(-11,0,i*1.1f),.48f);}Box(p,new Vector3(-10.8f,1.4f,-3.8f),new Vector3(.3f,2.8f,2),"Metal");for(int i=0;i<5;i++)Box(p,new Vector3(-10.55f,.8f+i*.33f,-3.8f),new Vector3(.08f,.07f,1.5f),"Edge");
 for(int s=-1;s<=1;s+=2)for(int i=0;i<6;i++)Box(p,new Vector3(s*6,.025f,-5+i*2),new Vector3(.15f,.015f,1),"Cream");Merge(p,"Auto repair workshop");
 var marking=New(p,"Service radius marking (unit radius)");Ring(marking,1);Merge(marking,"Service radius marking");marking.localScale=new Vector3(10,1,10);
 var effect=New(p,"Active repair icon");effect.localPosition=Vector3.up*4;Box(effect,Vector3.zero,new Vector3(1.4f,.25f,.18f),"Glow");Box(effect,Vector3.zero,new Vector3(.25f,1.4f,.18f),"Glow");effect.localRotation=Quaternion.Euler(0,180,0);Merge(effect,"Repair icon");effect.gameObject.SetActive(false);
 var repair=p.gameObject.AddComponent<RepairWorkshop>();repair.session=level.session;repair.healingRadius=10;repair.maximumHealthFractionPerSecond=.1f;repair.radiusMarking=marking;repair.activeRepairEffect=effect.gameObject;
 var ht=level.session.hud.healthText;var ui=new GameObject("Repairing indicator",typeof(RectTransform));ui.transform.SetParent(ht.transform.parent,false);var rt=(RectTransform)ui.transform;var source=(RectTransform)ht.transform;rt.anchorMin=source.anchorMin;rt.anchorMax=source.anchorMax;rt.pivot=source.pivot;rt.sizeDelta=new Vector2(250,27);rt.anchoredPosition=source.anchoredPosition+new Vector2(0,-34);var text=ui.AddComponent<Text>();text.font=ht.font;text.fontSize=21;text.alignment=TextAnchor.MiddleCenter;text.color=Hex("E5C681");text.text="REPAIRING";text.raycastTarget=false;repair.repairingLabel=text;ui.SetActive(false);
 }
 static void ExpandRoads(){var routes=level.decorationRoot.Find("00 · Routes and clear ground");foreach(Transform child in routes){if(child.name.Contains("Quiet grass")){child.position=X(child.position);Recolor(child);child.name="Cracked earth patch";continue;}foreach(var f in child.GetComponentsInChildren<MeshFilter>()){var r=f.GetComponent<MeshRenderer>();int road=Array.FindIndex(r.sharedMaterials,m=>m.name=="Road");if(road<0)continue;var old=f.sharedMesh;var m=new Mesh{indexFormat=IndexFormat.UInt32};var verts=old.vertices.Select(X).ToArray();m.vertices=verts;m.triangles=old.GetTriangles(road);m.uv=verts.Select(v=>new Vector2(v.x,v.z)/14).ToArray();m.RecalculateNormals();m.RecalculateBounds();AssetDatabase.CreateAsset(m,Root+"/Meshes/"+(meshId++)+"-worn-track.asset");f.sharedMesh=m;r.sharedMaterials=new[]{mat["Track"]};}child.name=child.name.Replace("Sanctuary","Service");}}
 static void Terrain(){var m=level.ground.sharedMesh;var vertices=m.vertices.Select(X).ToArray();for(int i=0;i<vertices.Length;i++){var v=vertices[i];float road=Mathf.Min(Mathf.Abs(v.x),Mathf.Abs(v.z-55));float weight=Mathf.SmoothStep(0,1,Mathf.InverseLerp(13,24,road));foreach(var p in flatSpots){var q=Quaternion.Inverse(Axis)*p;float d=Vector2.Distance(new Vector2(v.x,v.z),new Vector2(q.x,q.z));weight*=Mathf.SmoothStep(0,1,Mathf.InverseLerp(7,14,d));}v.y=.24f*Mathf.Sin(v.x*.085f)*Mathf.Sin(v.z*.065f)*weight;vertices[i]=v;}m.vertices=vertices;m.uv=vertices.Select(v=>new Vector2(v.x,v.z)/14).ToArray();m.RecalculateNormals();m.RecalculateBounds();EditorUtility.SetDirty(m);level.ground.GetComponent<MeshCollider>().sharedMesh=null;level.ground.GetComponent<MeshCollider>().sharedMesh=m;level.ground.GetComponent<Renderer>().sharedMaterial=mat["Sand"];level.ground.name="Wasteland — expanded driving terrain";EditorUtility.CopySerialized(m,level.baselineTerrain);EditorUtility.SetDirty(level.baselineTerrain);level.gameplayBounds=new Bounds(X(level.gameplayBounds.center),X(level.gameplayBounds.size));}
 static void Enemies(){var d=level.session.spawns;var originals=d.authoredRaiders.ToArray();var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RoadGunner/Prefabs/Wasteland Raider.prefab");var restored=new List<Raider>();for(int i=0;i<originals.Length;i++){var old=originals[i];var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab,old.transform.parent);g.name=i==12?"13 · Armored scrapyard veteran":old.name.Replace("sword and shield champion","raider captain");g.transform.SetPositionAndRotation(X(old.transform.position),old.transform.rotation);g.transform.localScale=old.transform.localScale;var r=g.GetComponent<Raider>();r.session=level.session;r.tuning=old.tuning;g.SetActive(true);foreach(var c in g.GetComponentsInChildren<Component>(true))if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);restored.Add(r);Object.DestroyImmediate(old.gameObject);}d.authoredRaiders=restored.ToArray();d.pool=d.pool.Where(r=>r).Concat(restored).Distinct().ToArray();foreach(var b in d.authoredBuggies)b.transform.position=X(b.transform.position);foreach(var e in d.encounters??Array.Empty<EncounterSpawn>()){e.transform.position=X(e.transform.position);if(e.spawnPoints!=null)foreach(var p in e.spawnPoints)p.localPosition=X(p.localPosition);}if(d.buggySpawnPoints!=null)foreach(var t in d.buggySpawnPoints)t.position=X(t.position);if(d.groupCenters!=null)d.groupCenters=d.groupCenters.Select(X).ToArray();
 // Three small patrol pairs on widened travel legs; no changes to the existing cap or tuning.
 var anchors=new[]{new Vector2(2,-20),new Vector2(-15,23),new Vector2(2,46)};int id=14;foreach(var a in anchors)for(int j=0;j<2;j++){var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab,level.humanEnemiesRoot);g.name=(id++)+" · Transit raider";g.transform.SetPositionAndRotation(W(a.x,a.y)+Axis*new Vector3(j*2.2f,0,0),Axis);var r=g.GetComponent<Raider>();r.session=level.session;r.tuning=restored[0].tuning;g.SetActive(true);foreach(var c in g.GetComponentsInChildren<Component>(true))if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}
 }
 static void ExtraDressing(){var p=New(level.decorationRoot,"H · Travel landmarks and shoulder salvage");var spots=new[]{new Vector2(-7,-34),new Vector2(8,-22),new Vector2(-9,6),new Vector2(-18,28),new Vector2(5,38),new Vector2(-6,49),new Vector2(26,22)};for(int i=0;i<spots.Length;i++){var at=W(spots[i].x,spots[i].y);PlaceNew(i%2==0?"Abandoned pickup":"Tire and scrap pile",p,at,Axis*Quaternion.Euler(0,35*i,0),Vector3.one);PlaceNew("Fuel drums",p,at+Axis*new Vector3(3,0,2),Axis,Vector3.one);}
 // Low, non-colliding broken earth accents distributed away from the driving centerline.
 for(int i=0;i<35;i++){float x=(i%2==0?-1:1)*(11+i%4*5),z=-37+i*2.7f;var t=New(p,"Cracked ground");t.SetPositionAndRotation(W(x,z,.02f),Axis);for(int j=0;j<4;j++)Box(t,new Vector3(j*.65f,0,(j%2)*.35f),new Vector3(.055f,.015f,1.2f),"Track",new Vector3(0,j*37,0));Merge(t,"Earth cracks");}
 }
 public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Stop play first");level=RoadGunnerLevelAuthoring.Current;if(level.gameObject.scene.path!=AstraZone01Builder.ScenePath)throw new Exception("Wrong scene");if(level.appliedFootprintScale!=1||Directory.Exists(Root))throw new Exception("Already applied; do not compound expansion");Directory.CreateDirectory(Root+"/Materials");Directory.CreateDirectory(Root+"/Meshes");Directory.CreateDirectory(Root+"/Prefabs");Directory.CreateDirectory(Report);AssetDatabase.Refresh();Palette();Prepare();
 var before=level.ground.GetComponent<Renderer>().bounds;var bounds=level.gameplayBounds;var spawn=level.playerSpawn.position;
 foreach(var root in new[]{level.obstaclesRoot,level.decorationRoot})foreach(Transform section in root)foreach(Transform t in section)if(t.GetComponentsInChildren<Collider>().Any())flatSpots.Add(X(t.position));
 ExpandRoads();foreach(Transform section in level.obstaclesRoot)ConvertSection(section,true);foreach(Transform section in level.decorationRoot)if(!section.name.StartsWith("00 ·"))ConvertSection(section,false);
 Terrain();Enemies();foreach(var t in level.recoveryPoints.Distinct())t.position=X(t.position);if(!level.recoveryPoints.Contains(level.playerSpawn))level.playerSpawn.position=X(spawn);
 var workshop=Object.FindAnyObjectByType<RepairWorkshop>();var recovery=level.recoveryPoints.FirstOrDefault(t=>t!=level.playerSpawn);if(recovery){recovery.position=workshop.transform.position+Axis*new Vector3(0,.7f,-3);recovery.name="Workshop recovery — clear service apron";}
 ExtraDressing();level.levelName="01 · Rust Frontier";level.requestedFootprintScale=level.appliedFootprintScale=2.5f;level.authoringNotes="Existing Greenwood layout restored to Road Gunner wasteland. ONE 2.5x world X/Z expansion from saved 124x146 m terrain; car, ordinary props, stats and physics unscaled. Checkpoint and validation: "+Report;level.session.vehicle.transform.SetPositionAndRotation(level.playerSpawn.position,level.playerSpawn.rotation);level.session.follow.Snap();level.session.follow.GetComponent<Camera>().backgroundColor=Hex("BDA17A");RenderSettings.ambientSkyColor=Hex("DDD4BB");RenderSettings.ambientEquatorColor=Hex("B9A583");RenderSettings.ambientGroundColor=Hex("77624F");foreach(var light in RoadGunnerLevelAuthoring.InScene<Light>())if(light.type==LightType.Directional){light.color=Hex("FFF0D7");light.intensity=1.05f;}
 RoadGunnerLevelAuthoring.Save(level);var after=level.ground.GetComponent<Renderer>().bounds;File.WriteAllText(Report+"/Expansion.txt","Scene: "+level.gameObject.scene.path+"\nGround local X/Z: 124 x 146 m -> 310 x 365 m\nGround world AABB before="+before+"\nafter="+after+"\nConfigured gameplay bounds before="+bounds+"\nafter="+level.gameplayBounds+"\nScale applied once: 2.5 per horizontal axis; 6.25 ground area. Root scale="+level.transform.localScale+"\nOriginal 13 encounter roles retained; 6 transit raiders added. Active cap="+level.session.spawns.tuning.activeCap+"\nWorkshop radius=10 m, rate=0.1 of maximum HP per scaled second.\n");return File.ReadAllText(Report+"/Expansion.txt");}
